CREATE TABLE customers (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email TEXT NOT NULL UNIQUE
);

CREATE TABLE orders (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id BIGINT NOT NULL
    REFERENCES customers(id) ON DELETE RESTRICT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_orders_customer_id ON orders(customer_id);

CREATE TABLE carts (
  id BIGINT PRIMARY KEY
);

CREATE TABLE cart_items (
  cart_id BIGINT REFERENCES carts(id) ON DELETE CASCADE,
  product_id BIGINT NOT NULL,
  quantity INT NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (cart_id, product_id)
);

DELETE FROM carts WHERE id = 12;
-- Cart 12 and all its cart_items are deleted.

CREATE TABLE support_tickets (
  id BIGINT PRIMARY KEY,
  assigned_employee_id BIGINT NULL
    REFERENCES employees(id) ON DELETE SET NULL
);

DELETE FROM employees WHERE id = 7;
-- Tickets assigned to employee 7 remain,
-- but assigned_employee_id becomes NULL.

CREATE TABLE teams (
  id BIGINT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

INSERT INTO teams (id, name) VALUES (0, 'Unassigned');

CREATE TABLE tickets (
  id BIGINT PRIMARY KEY,
  team_id BIGINT NOT NULL DEFAULT 0
    REFERENCES teams(id) ON DELETE SET DEFAULT
);

-- Deleting a non-default team moves its tickets to team_id = 0.
-- Team 0 must remain present for the foreign key to stay valid.

CREATE TABLE seats (
  person TEXT PRIMARY KEY,
  seat_no INT UNIQUE
);
INSERT INTO seats VALUES ('Alice', 1), ('Ben', 2);
UPDATE seats SET seat_no = 2 WHERE person = 'Alice';
-- Fails: Ben already has seat_no = 2.

CREATE TABLE seats (
  person TEXT PRIMARY KEY,
  seat_no INT,
  CONSTRAINT seats_seat_no_uq UNIQUE (seat_no)
    DEFERRABLE INITIALLY IMMEDIATE
);
INSERT INTO seats VALUES ('Alice', 1), ('Ben', 2);

BEGIN;
SET CONSTRAINTS seats_seat_no_uq DEFERRED;
UPDATE seats SET seat_no = 2 WHERE person = 'Alice';
UPDATE seats SET seat_no = 1 WHERE person = 'Ben';
COMMIT;

SET CONSTRAINTS seats_seat_no_uq DEFERRED;
-- Later, check it immediately again:
SET CONSTRAINTS seats_seat_no_uq IMMEDIATE;

CREATE TABLE users (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  username TEXT NOT NULL UNIQUE
);
INSERT INTO users (username)
VALUES ('aman')
ON CONFLICT (username) DO NOTHING;
